class Solution {
  public int maxSum(int[] nums, int k, int m) {
    int n = nums.length;
    int NEG = Integer.MIN_VALUE / 2;
    int[] pre = new int[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    int[][] dp = new int[n + 1][k + 1];
    for (int[] row : dp) java.util.Arrays.fill(row, NEG);
    for (int i = 0; i <= n; i++) dp[i][0] = 0;
    int[] best = new int[k + 1];
    java.util.Arrays.fill(best, NEG);
    for (int i = 1; i <= n; i++) {
      int l = i - m;
      if (l >= 0) {
        for (int j = 1; j <= k; j++) {
          if (dp[l][j - 1] > NEG) best[j] = Math.max(best[j], dp[l][j - 1] - pre[l]);
        }
      }
      for (int j = 1; j <= k; j++) {
        int v = dp[i - 1][j];
        if (best[j] > NEG) v = Math.max(v, best[j] + pre[i]);
        dp[i][j] = v;
      }
    }
    return dp[n][k];
  }
}
